import os
import json

d = os.environ['RLM_SESSION_DIR']
session_file = os.path.join(d, '..', 'sessions', os.path.basename(d) + '.jsonl')

with open(session_file, 'r') as f:
    content = f.read()

# Extract all grids systematically
grids = {}
current_key = None
current_grid = []

for line in content.split('\n'):
    if 'input (24x18)' in line or 'input (11x17)' in line:
        if current_key and current_grid:
            grids[current_key] = current_grid
        current_key = line.split('(')[0].strip()
        current_grid = []
    elif line.isdigit():
        current_grid.append(list(map(int, line.split())))

if current_key and current_grid:
    grids[current_key] = current_grid

for k, g in grids.items():
    print(f"\n=== {k} ===")
    for row in g:
        print(' '.join(str(x) for x in row))

